floor_fn:
"""Converts distance in meters to miles

  Args:
    value: floating point representing the distance in meters
  Returns: distance in miles
  """
def m_to_mile(value: Any) -> object {
    if (value is None) {
        return None;
    }
    return (value / 1609);
}

test_blocks:
test "t0" {
    assert (m_to_mile(0) == 0.0);;
}

test "t1" {
    assert (m_to_mile(None) == None);;
}

test "t2" {
    assert (m_to_mile(0) == 0);;
}

test "t3" {
    assert (m_to_mile(1609) == 1);;
}

test "t4" {
    assert (m_to_mile(1609) == 1.0);;
}
